javascript(/**
* @param {params} params
* @param {api} params.api
* @param {any} params.event
*/
function evaluateEvent({api, event}) {
	return {
		prevQuery: event.payload.prevQuery,
		table: event.payload.table,
		query: event.payload.query,
		fixedQuery: event.payload.fixedQuery
	};
})

